(function(root){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function today(now=new Date()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day;}
function validate(rows){if(!Array.isArray(rows))throw Error('Funding records must be an array.');const ids=new Set();for(const p of rows){for(const key of ['id','name','audience','purpose','scheduleKind','deadlineText','notes','url','checked'])if(typeof p[key]!=='string'||!p[key].trim())throw Error('Funding record missing '+key);const url=new URL(p.url);if(url.protocol!=='https:'||!(url.hostname==='lsuhsc.edu'||url.hostname.endsWith('.lsuhsc.edu')))throw Error('Funding calendar is limited to LSU Health sources.');if(ids.has(p.id))throw Error('Duplicate funding ID');ids.add(p.id);if(!['recurring','rolling','dated','unannounced'].includes(p.scheduleKind))throw Error('Unknown deadline type');if(p.scheduleKind==='recurring'&&(!Array.isArray(p.monthDays)||!p.monthDays.length||p.monthDays.some(d=>!/^\d{2}-\d{2}$/.test(d))))throw Error('Missing recurring dates');if(p.scheduleKind==='dated'&&!/^\d{4}-\d{2}-\d{2}$/.test(p.deadline||''))throw Error('Missing dated call');}return rows;}
function nextDate(p,day){if(p.scheduleKind==='dated')return p.deadline>=day?p.deadline:null;if(p.scheduleKind!=='recurring')return null;const year=Number(day.slice(0,4));return [year,year+1].flatMap(y=>p.monthDays.map(md=>y+'-'+md)).sort().find(d=>d>=day)||null;}
function status(p,day){if(p.scheduleKind==='recurring')return 'Recurring Schedule — Confirm Current Call';if(p.scheduleKind==='rolling')return 'Rolling Submission — Confirm Availability';if(p.scheduleKind==='dated')return p.deadline<day?'Past Call — Next Cycle Not Announced':'Dated Call — Confirm Availability';return 'No Fixed Deadline Posted';}
function label(day){return new Date(day+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});}
function searchRecords(rows){return validate(rows).map(p=>({id:'funding-'+p.id,name:p.name,summary:p.purpose+' '+p.audience+' '+p.deadlineText,url:'#microgrants?intramural=1',type:'funding',category:'Funding and career development',topic:'LSU Health intramural funding',access:p.notes,tags:[p.id,'intramural','funding','deadline',p.name,p.audience]}));}
function render(rows,open=false,now=new Date()){const day=today(now),items=validate(rows);return `<section class="section intramural-secondary"><div class="container"><details id="other-intramural-funding" ${open?'open':''}><summary>Other LSU Health Intramural Funding</summary><p class="quiet-note">Additional options beyond Lowenstein PCCM Micro-Grants. These programs have their own eligibility, application, and review requirements.</p><p class="quiet-note">Recurring dates are planning dates from official guidance, not confirmation that a competition is open. Check the program link for the current call, cutoff, and any holiday adjustments.</p><div class="funding-table-wrap" role="region" aria-label="LSU Health Intramural Funding Deadlines" tabindex="0"><table class="funding-table"><caption>Published Schedules and Application Timing</caption><thead><tr><th scope="col">Program</th><th scope="col">Who It Supports</th><th scope="col">Timing and Status</th></tr></thead><tbody>${items.map(p=>{const next=nextDate(p,day);const old=(new Date(day+'T12:00:00Z')-new Date(p.checked+'T12:00:00Z'))/86400000>120;return `<tr><th scope="row"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.name)} ↗</a><p>${esc(p.purpose)}</p></th><td>${esc(p.audience)}</td><td><strong>${esc(status(p,day))}</strong>${next?`<p>Next ${p.scheduleKind==='recurring'?'Nominal Date':'Listed Deadline'}: ${esc(label(next))}${next===day?' (today; confirm cutoff)':''}</p>`:''}<p>${esc(p.deadlineText)}</p><details><summary>Program Notes</summary><p>${esc(p.notes)}</p></details><small>Source checked ${esc(label(p.checked))}${old?' · Schedule Needs Rechecking':''}</small></td></tr>`;}).join('')}</tbody></table></div></details></div></section>`;}
const api={today,validate,nextDate,status,searchRecords,render};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.IntramuralFunding=api;
})(typeof window!=='undefined'?window:globalThis);
